    #[cfg(not(target_arch = "wasm32"))]
    #[doc(hidden)]
    pub fn set_fail_drop_safe_hold_spawn_for_test(&self, fail: bool) {
        self.fail_drop_safe_hold_spawn.store(fail, Ordering::Release);
    }

    pub fn internal_fault_lane(&self) -> &Arc<crate::panic_coord::InternalFaultLane> {
        &self.internal_fault_lane
    }

    #[inline]
    pub fn internal_fault_fenced(&self) -> bool {
        self.internal_fault_lane.is_fenced()
    }

    pub fn legacy_safe_hold_control(&self) -> Arc<crate::rt_core::safe_hold::SafeHoldControl> {
        Arc::clone(&self.legacy_safe_hold)
    }

    /// Registers the active legacy control loop's stop flag on the authoritative writer endpoint.
    pub fn register_legacy_control_stop(&self, stop: Arc<AtomicBool>) {
        let mut w = self.active_writer.lock().unwrap_or_else(|e| e.into_inner());
        if matches!(*w, WriterEndpoint::Legacy { .. }) {
            *w = WriterEndpoint::Legacy {
                control_stop: Some(stop),
                safe_hold: Arc::clone(&self.legacy_safe_hold),
            };
        }
    }

    /// Returns a snapshot of the authoritative active bus-writer endpoint (B4).
    pub fn active_writer_endpoint(&self) -> WriterEndpoint {
        self.active_writer
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .clone()
    }

    /// True if a detached `armd-control` thread currently holds an energized/unknown-state driver
    /// in SAFE-HOLD (e.g. after a startup timeout or stalled handback).
    pub fn has_detached_safe_hold(&self) -> bool {
        match self.active_writer_endpoint() {
            WriterEndpoint::DetachedSafeHold { safe_hold, .. } => !safe_hold.is_exited(),
            WriterEndpoint::Executor(h) => {
                let sh = h.safe_hold_control();
                sh.is_active() && !sh.is_exited()
            }
            WriterEndpoint::Legacy { safe_hold, .. } => {
                safe_hold.is_active() && !safe_hold.is_exited()
            }
            WriterEndpoint::Transferring => false,
        }
    }

    /// True ONLY once the active writer's `armd-control` thread has actually entered the
    /// SAFE-HOLD loop (`safe_hold.is_active() && !safe_hold.is_exited()`).
    pub fn is_detached_safe_hold_active(&self) -> bool {
        match self.active_writer_endpoint() {
            WriterEndpoint::DetachedSafeHold { safe_hold, .. } => {
                safe_hold.is_active() && !safe_hold.is_exited()
            }
            WriterEndpoint::Executor(h) => {
                let sh = h.safe_hold_control();
                sh.is_active() && !sh.is_exited()
            }
            WriterEndpoint::Legacy { safe_hold, .. } => {
                safe_hold.is_active() && !safe_hold.is_exited()
            }
            WriterEndpoint::Transferring => false,
        }
    }

    /// Returns the active writer's [`SafeHoldControl`] handle for observability and testing.
    pub fn active_safe_hold_control(&self) -> Arc<crate::rt_core::safe_hold::SafeHoldControl> {
        match self.active_writer_endpoint() {
            WriterEndpoint::DetachedSafeHold { safe_hold, .. } => safe_hold,
            WriterEndpoint::Executor(h) => h.safe_hold_control(),
            WriterEndpoint::Legacy { safe_hold, .. } => safe_hold,
            WriterEndpoint::Transferring => Arc::clone(&self.legacy_safe_hold),
        }
    }

    /// Shared Legacy `armd-control` loop body with tiered panic recovery (FU-PANIC / DRV-F1):
    /// - Enters [`crate::panic_coord::ControlPanicScope`] so the process panic hook routes
    ///   control-thread panics to local `catch_unwind` -> SAFE-HOLD.
    /// - Preallocates [`crate::rt_core::safe_hold::SafeHoldBuffers`] before the loop and mirrors
    ///   last fresh measured positions after every clean tick.
    /// - On an unwind panic inside a legacy control tick while a hardware driver is attached and
    ///   not confirmed disarmed: fences all commands/rearm, extracts the `Box<dyn ArmDriver>`
    ///   exclusively ONCE (recovering poison if needed), and transitions into the zero-alloc,
    ///   zero-lock SAFE-HOLD loop until thermal trip or deliberate `ProcessExit` protective disable.
    pub fn run_legacy_control_loop_blocking(
        self: &Arc<Self>,
        period: Duration,
        control_stop: Arc<AtomicBool>,
        loop_stats: Arc<crate::rt_core::executor::ExecutorStats>,
        runtime: tokio::runtime::Handle,
        panic_hook_step: Option<Arc<AtomicU64>>,
    ) {
        let _panic_scope = crate::panic_coord::ControlPanicScope::enter();
        self.register_legacy_control_stop(Arc::clone(&control_stop));
        let cfg = runtime.block_on(async { self.inner().read().await.config.clone() });
        let mut safe_hold_bufs =
            crate::rt_core::safe_hold::SafeHoldBuffers::from_config(&cfg, period);
        {
            let guard = runtime.block_on(self.inner.read());
            safe_hold_bufs.attach_stop_mirrors(
                Arc::clone(&self.estop_state),
                Arc::clone(&guard.estop_applied),
                guard.stop_requests.clone(),
            );
        }
        let safe_hold_ctrl = Arc::clone(&self.legacy_safe_hold);
        #[cfg(not(target_arch = "wasm32"))]
        let mut disabled_shadow_spare = Some(crate::torque::shadow::ShadowRuntime::disabled(&cfg));
        let mut step_counter: u64 = 0;
        let mut panicked = false;
        let mut handoff_driver: Option<Box<dyn ArmDriver>> = None;
        #[cfg(not(target_arch = "wasm32"))]
        let mut handoff_shadow: Option<crate::torque::shadow::ShadowRuntime> = None;
        let mut handoff_reason: Option<crate::rt_core::safe_hold::SafeHoldReason> = None;

        crate::rt_core::executor::run_periodic_with_deadline(
            period,
            &control_stop,
            &loop_stats,
            |dt, release_deadline| {
                step_counter = step_counter.saturating_add(1);
                let mut extracted: Option<(
                    Box<dyn ArmDriver>,
                    Option<crate::torque::shadow::ShadowRuntime>,
                    crate::rt_core::safe_hold::SafeHoldReason,
                )> = None;
                let tick_res = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    if panic_hook_step
                        .as_ref()
                        .is_some_and(|target| target.load(Ordering::Acquire) == step_counter)
                    {
                        panic!("simulated legacy control thread panic at tick {step_counter}");
                    }
                    runtime.block_on(self.tick_shared_with_handoff(
                        dt,
                        false,
                        Some(release_deadline),
                        Some((
                            &mut safe_hold_bufs,
                            &control_stop,
                            &mut disabled_shadow_spare,
                            &mut extracted,
                        )),
                    ));
                }));
                match tick_res {
                    Ok(()) => {
                        if let Some((drv, sh, reason)) = extracted {
                            handoff_driver = Some(drv);
                            #[cfg(not(target_arch = "wasm32"))]
                            {
                                handoff_shadow = sh;
                            }
                            #[cfg(target_arch = "wasm32")]
                            let _ = sh;
                            handoff_reason = Some(reason);
                            control_stop.store(true, Ordering::Release);
                        }
                    }
                    Err(_) => {
                        panicked = true;
                        crate::rt_core::executor::account_periodic_overrun_on_panic_exit(
                            &loop_stats,
                        );
                        self.estop_state.latch();
                        self.internal_fault_lane.latch_control_safe_hold_fence();
                        tracing::error!(
                            "Legacy control thread panicked during tick {step_counter}; transitioning to SAFE-HOLD"
                        );
                        control_stop.store(true, Ordering::Release);
                    }
                }
            },
        );

        // Unified Legacy loop exit disposition (DRV-F1 B1/B2/B5 + PR0C Blocker 7):
        // - If `tick_shared_with_handoff` already extracted the driver directly under its own
        //   single write guard (e.g. `SessionUncertainState`), enter SAFE-HOLD immediately with
        //   zero extra lock attempts and zero contention delay.
        // - Otherwise handle panic / teardown-while-energized via bounded extraction.
        if let Some(mut drv) = handoff_driver {
            let reason = handoff_reason
                .unwrap_or(crate::rt_core::safe_hold::SafeHoldReason::SessionUncertainState);
            #[cfg(not(target_arch = "wasm32"))]
            let _ = safe_hold_bufs.run_loop_with_shadow(
                drv.as_mut(),
                &safe_hold_ctrl,
                reason,
                Instant::now,
                std::thread::sleep,
                handoff_shadow.as_mut(),
            );
            #[cfg(target_arch = "wasm32")]
            let _ = safe_hold_bufs.run_loop(
                drv.as_mut(),
                &safe_hold_ctrl,
                reason,
                Instant::now,
                std::thread::sleep,
            );
            return;
        }
        {
            let reason = if panicked {
                crate::rt_core::safe_hold::SafeHoldReason::ControlPanic
            } else {
                crate::rt_core::safe_hold::SafeHoldReason::TeardownWhileEnergized
            };
            if panicked {
                safe_hold_ctrl.mark_active(reason);
                #[cfg(not(target_arch = "wasm32"))]
                self.torque_shadow.wake();
            }
            let mut extracted_driver: Option<Box<dyn ArmDriver>> = None;
            #[cfg(not(target_arch = "wasm32"))]
            let mut extracted_shadow: Option<crate::torque::shadow::ShadowRuntime> = None;
            loop {
                if let Ok(mut guard) = self.inner.try_write() {
                    if !guard.detached && !guard.shutdown_committed {
                        let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                            #[cfg(not(target_arch = "wasm32"))]
                            guard.on_safe_hold_enter(if panicked {
                                "CONTROL_PANIC"
                            } else {
                                "SAFE_HOLD"
                            });
                            safe_hold_bufs.seed_on_entry(&guard);
                            #[cfg(not(target_arch = "wasm32"))]
                            if panicked {
                                let live_intent = guard.shadow_live_intent();
                                let live_is_torqued = guard.is_torqued;
                                guard.torque_shadow.enqueue(
                                    crate::torque::shadow::ShadowInputKind::Panic {
                                        tier: crate::torque::PanicTier::CaughtControlPanic,
                                        live_intent,
                                        live_is_torqued,
                                        live_stopped: true,
                                    },
                                );
                                guard.flush_torque_shadow();
                            }
                        }));
                        if !crate::rt_core::executor::core_is_confirmed_disarmed(&guard) {
                            self.estop_state.latch();
                            self.internal_fault_lane.latch_control_safe_hold_fence();
                            safe_hold_ctrl.mark_active(reason);
                            #[cfg(not(target_arch = "wasm32"))]
                            if !panicked {
                                let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                                    let live_intent = guard.shadow_live_intent();
                                    let live_is_torqued = guard.is_torqued;
                                    guard.torque_shadow.enqueue(
                                        crate::torque::shadow::ShadowInputKind::Stop {
                                            kind: crate::torque::StopKind::EStop,
                                            live_intent,
                                            live_is_torqued,
                                            live_stopped: true,
                                        },
                                    );
                                    guard.flush_torque_shadow();
                                }));
                            }
                            extracted_driver = guard
                                .driver
                                .take()
                                .map(crate::supervisor_lock::DriverSlot::into_driver_recover_for_safe_hold);
                            if extracted_driver.is_some() {
                                // Atomically detach the shell AND publish `OwnerSlot::Failed` +
                                // `WriterEndpoint::DetachedSafeHold` inside the same write-guard
                                // transaction so `try_set_driver()` and `start_executor()` can
                                // NEVER admit a second bus writer while SAFE-HOLD runs (DRV-F1 B1).
                                guard.detached = true;
                                #[cfg(not(target_arch = "wasm32"))]
                                {
                                    let disabled =
                                        crate::torque::shadow::ShadowRuntime::disabled(&guard.config);
                                    extracted_shadow = Some(std::mem::replace(
                                        &mut guard.torque_shadow,
                                        disabled,
                                    ));
                                }
                                {
                                    let mut slot =
                                        self.owner.lock().unwrap_or_else(|e| e.into_inner());
                                    *slot = OwnerSlot::Failed;
                                    self.owner_mode.store(OWNER_FAILED, Ordering::Release);
                                }
                                {
                                    let mut w = self
                                        .active_writer
                                        .lock()
                                        .unwrap_or_else(|e| e.into_inner());
                                    *w = WriterEndpoint::DetachedSafeHold {
                                        safe_hold: Arc::clone(&safe_hold_ctrl),
                                        control_stop: Arc::clone(&control_stop),
                                    };
                                }
                            }
                        }
                    }
                    break;
                }
                if safe_hold_ctrl.process_exit_requested() {
                    // Process exit requested while shell write guard is still contended: run
                    // bounded legacy panic disable once the lock frees within the exit deadline.
                    self.process_exit_requested.store(true, Ordering::Release);
                    let dl = safe_hold_ctrl.process_exit_deadline();
                    let rem = dl.saturating_duration_since(Instant::now());
                    let outcome = self.attempt_legacy_panic_disable(rem);
                    safe_hold_ctrl.record_process_exit_outcome_lockfree(&outcome);
                    safe_hold_ctrl.mark_exited();
                    if matches!(
                        outcome,
                        PanicDisableOutcome::Confirmed | PanicDisableOutcome::NoDriver
                    ) {
                        return;
                    }
                    // Unconfirmed/TimedOut/Failed: continue looping to acquire the shell lock and
                    // retain the energized driver in SAFE-HOLD rather than returning to drop it.
                }
                std::thread::sleep(Duration::from_millis(1));
            }
            if let Some(mut drv) = extracted_driver {
                #[cfg(not(target_arch = "wasm32"))]
                let _ = safe_hold_bufs.run_loop_with_shadow(
                    drv.as_mut(),
                    &safe_hold_ctrl,
                    reason,
                    Instant::now,
                    std::thread::sleep,
                    extracted_shadow.as_mut(),
                );
                #[cfg(target_arch = "wasm32")]
                let _ = safe_hold_bufs.run_loop(
                    drv.as_mut(),
                    &safe_hold_ctrl,
                    reason,
                    Instant::now,
                    std::thread::sleep,
                );
                drop(drv);
            } else if panicked {
                safe_hold_ctrl.mark_exited();
            }
        }
    }

    /// Forbidden legacy `DriverLock` acquisition attempts observed on `armd-control`.
    pub fn driver_lock_attempts(&self) -> u64 {
        self.driver_lock_attempts.load(Ordering::Acquire)
    }

    /// Shared atomic counter for positive-control tests verifying `DriverLock` instrumentation.
    #[doc(hidden)]
    pub fn driver_lock_attempts_counter(&self) -> Arc<AtomicU64> {
        Arc::clone(&self.driver_lock_attempts)
    }

    /// Spawns at most one bounded off-lock cleanup task in headless mode (when no live control
    /// loop is ticking) so a contended `DetachedCancel` or expired `Detached` disable left behind
    /// after waiter timeout still drains once the driver mutex frees. Exits immediately if a live
    /// control tick advances `control_release_seq` or ownership transfers.
    fn spawn_headless_detached_drain_if_needed(&self, observed_seq: u64) {
        if self
            .headless_detached_drain_active
            .compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire)
            .is_err()
        {
            return;
        }
        let inner_lock = Arc::clone(&self.inner);
        let active_flag = Arc::clone(&self.headless_detached_drain_active);
        let notify = Arc::clone(&self.legacy_torque_notify);
        tokio::spawn(async move {
            struct ClearFlag(Arc<AtomicBool>);
            impl Drop for ClearFlag {
                fn drop(&mut self) {
                    self.0.store(false, Ordering::Release);
                }
            }
            let _guard = ClearFlag(active_flag);
            const DRAIN_INTERVAL: Duration = Duration::from_millis(25);
            const DRAIN_BUDGET: Duration = Duration::from_micros(500);
            let hard_deadline = Instant::now() + Duration::from_secs(5);
            while Instant::now() < hard_deadline {
                tokio::time::sleep(DRAIN_INTERVAL).await;
                let (keep_going, settled_any) = {
                    let mut inner = inner_lock.write().await;
                    let io_scope = crate::diagnostics::tick::HoldIoScope::enter();
                    inner.set_command("/api/v1/torque");
                    if let Some(dir) = match inner.torque_transition {
                        Some(driver_transitions::TorqueTransition::Enable(_)) => Some("on"),
                        Some(driver_transitions::TorqueTransition::Disable { .. }) => Some("off"),
                        None => None,
                    } {
                        inner.set_direction(dir);
                    }
                    let res = if inner.detached
                        || inner.control_release_seq != observed_seq
                        || !inner.has_detached_torque_transition()
                    {
                        (false, false)
                    } else {
                        let now = Instant::now();
                        let budget = crate::rt_core::ops::ServiceBudget {
                            now,
                            deadline: now + DRAIN_BUDGET,
                            max_rx_frames: crate::rt_core::ops::RX_FRAME_BUDGET,
                        };
                        #[cfg(not(target_arch = "wasm32"))]
                        {
                            let live_intent = inner.shadow_live_intent();
                            let live_is_torqued = inner.is_torqued;
                            let live_stopped = inner.safety.state().is_stopped();
                            inner.torque_shadow.enqueue_at(
                                now,
                                crate::torque::shadow::ShadowInputKind::TransitionWake {
                                    live_intent,
                                    live_is_torqued,
                                    live_stopped,
                                },
                            );
                        }
                        let _ = inner.service_torque_transition(&budget);
                        inner.flush_torque_shadow();
                        let settled =
                            std::mem::replace(&mut inner.legacy_torque_settled_this_tick, false);
                        (inner.has_detached_torque_transition(), settled)
                    };
                    inner.set_io_timing(io_scope.finish());
                    res
                };
                if settled_any {
                    notify.notify_waiters();
                }
                if !keep_going {
                    break;
                }
            }
        });
    }

    /// Test-only override for legacy WS `/api/v1/torque` request deadline (0 / `None` = default 5 s).
    #[doc(hidden)]
    pub fn set_legacy_torque_deadline_for_test(&self, deadline: Option<Duration>) {
        let ms = deadline.map_or(0, |d| d.as_millis().clamp(1, u128::from(u64::MAX)) as u64);
        self.legacy_torque_deadline_override_ms
            .store(ms, Ordering::Release);
    }

    /// Owner-aware storage of a `measure_multiview` measurement payload for action `id`.
    /// On `OWNER_EXECUTOR`, stores in `self.hub` (never touching `SupervisorLock` or `armd-control`)
    /// so `StateHub::refresh` attaches `action.measurement` into every published observation and
    /// delivered terminal identically to the Legacy owner.
    pub async fn record_action_measurement(&self, id: u64, value: serde_json::Value) {
        if self.owner_mode() == OWNER_EXECUTOR {
            self.hub.record_action_measurement(id, value);
        } else {
            self.inner()
                .write()
                .await
                .update_action(id, |a| a.measurement = Some(value));
        }
    }

    /// Owner-aware readback of the measurement payload recorded for action `id`.
    /// Never touches `SupervisorLock` when `OWNER_EXECUTOR` is active.
    pub async fn action_measurement(&self, id: u64) -> Option<serde_json::Value> {
        if self.owner_mode() == OWNER_EXECUTOR {
            self.hub.action_measurement(id)
        } else {
            let inner = self.inner().read().await;
            inner
                .last_action
                .as_ref()
                .filter(|a| a.id == id)
                .and_then(|a| a.measurement.clone())
                .or_else(|| {
                    inner
                        .previous_action
                        .as_ref()
                        .filter(|(a, _)| a.id == id)
                        .and_then(|(a, _)| a.measurement.clone())
                })
        }
    }

    /// Owner-aware storage of a `calib_hover` job record (never touches `SupervisorLock` in
    /// `OWNER_EXECUTOR` mode, and re-checks detachment if a handoff lands while waiting on the
    /// legacy write lock).
    pub async fn put_hover_job(&self, job: crate::calib_hover::HoverJob) {
        if self.owner_mode() == OWNER_EXECUTOR {
            self.put_executor_hover_job(job);
            return;
        }
        let mut inner = self.inner().write().await;
        if inner.detached {
            drop(inner);
            if self.owner_mode() == OWNER_EXECUTOR {
                self.put_executor_hover_job(job);
            }
            return;
        }
        inner.hover_jobs.retain(|j| j.id != job.id);
        inner.hover_jobs.push(job);
        let n = inner.hover_jobs.len();
        if n > crate::calib_hover::KEEP_JOBS {
            inner.hover_jobs.drain(..n - crate::calib_hover::KEEP_JOBS);
        }
    }

    fn put_executor_hover_job(&self, job: crate::calib_hover::HoverJob) {
        let mut jobs = self
            .executor_hover_jobs
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        jobs.retain(|j| j.id != job.id);
        jobs.push(job);
        let n = jobs.len();
        if n > crate::calib_hover::KEEP_JOBS {
            jobs.drain(..n - crate::calib_hover::KEEP_JOBS);
        }
    }

    /// Owner-aware snapshot of stored `calib_hover` jobs (never touches `SupervisorLock` in
    /// `OWNER_EXECUTOR` mode, and re-checks detachment if a handoff lands while waiting on the
    /// legacy read lock).
    pub async fn hover_jobs_snapshot(&self) -> Vec<crate::calib_hover::HoverJob> {
        if self.owner_mode() == OWNER_EXECUTOR {
            return self
                .executor_hover_jobs
                .lock()
                .unwrap_or_else(|e| e.into_inner())
                .clone();
        }
        let inner = self.inner().read().await;
        if inner.detached {
            drop(inner);
            if self.owner_mode() == OWNER_EXECUTOR {
                return self
                    .executor_hover_jobs
                    .lock()
                    .unwrap_or_else(|e| e.into_inner())
                    .clone();
            }
            return Vec::new();
        }
        inner.hover_jobs.clone()
    }

    /// Current live `SequenceStore::revision` mirror used to linearize episode deletes against
    /// concurrent `Sequences` save commits without blocking on `config_write_mutex`.
    pub fn sequences_revision(&self) -> u64 {
        self.sequences_revision.load(Ordering::Acquire)
    }

    pub(crate) fn set_sequences_revision(&self, rev: u64) {
        self.sequences_revision.store(rev, Ordering::Release);
    }

    /// Checks on the single live owner (`Legacy` or `Executor`) whether episode `id` is free of
    /// saved, running, or reserved sequence references (`409 IN_USE` otherwise).
    pub async fn check_episode_delete_allowed(&self, id: &str) -> Result<(), ArmError> {
        use crate::rt_core::requests::config::{ConfigReply, ConfigRequest};
        if self.owner_mode() == OWNER_LEGACY {
            let inner = self.inner.read().await;
            inner.episode_delete_allowed(id)?;
            if inner.episodes.is_pinned(id) {
                return Err(ArmError::detailed(
                    409,
                    "IN_USE",
                    format!("Episode '{id}' is reserved by an in-progress sequence save"),
                    serde_json::json!({"sequences": ["pending_save"]}),
                ));
            }
            return Ok(());
        }
        match self
            .dispatch_config_request_owned_reliable(ConfigRequest::CheckEpisodeDeleteAllowed(
                crate::model::HolderLabel::new(id),
            ))
            .await
        {
            Ok(ConfigReply::EpisodeDeleteAllowed(true)) => Ok(()),
            Ok(ConfigReply::EpisodeDeleteAllowed(false)) => {
                let mut users = self
                    .published_config()
                    .await
                    .map(|p| p.sequences.using_episode(id))
                    .unwrap_or_default();
                if users.is_empty() {
                    users.push("pending_save".to_string());
                }
                Err(ArmError::detailed(
                    409,
                    "IN_USE",
                    format!("Episode '{id}' is used by {} sequence(s)", users.len()),
                    serde_json::json!({"sequences": users}),
                ))
            }
            Err(e) => Err(e.to_arm_error()),
            _ => Err(ArmError::Internal("unexpected CheckEpisodeDeleteAllowed reply".into())),
        }
    }

    /// Linearizably verifies episode `id` is unreferenced (saved, running, or reserved) on the
    /// live owner, removes it from the `EpisodeStore` catalog on a blocking thread (off the Tokio
    /// worker), and returns its RAII deletion claim guard (`Some(guard)`) if removed, `None` if
    /// absent, or `Err(409 IN_USE)` if referenced. Dropping the guard on async cancellation marks
    /// the claim retryable so the episode ID is never stranded.
    pub async fn take_episode_for_delete_claim(
        &self,
        id: &str,
    ) -> Result<Option<crate::recording::store::EpisodeDeleteClaimGuard>, ArmError> {
        use crate::recording::store::TakeEpisodeOutcome;
        loop {
            let rev0 = self.sequences_revision();
            self.check_episode_delete_allowed(id).await?;
            let store = self.try_episode_store().await?;
            let id_owned = id.to_string();
            let seq_rev = Arc::clone(&self.sequences_revision);
            let outcome = tokio::task::spawn_blocking(move || {
                store.take_if_unpinned_and_rev_matches(&id_owned, &seq_rev, rev0)
            })
            .await
            .map_err(|e| ArmError::Internal(format!("episode delete take failed: {e}")))?;
            match outcome {
                TakeEpisodeOutcome::Removed(guard) => return Ok(Some(guard)),
                TakeEpisodeOutcome::NotFound => return Ok(None),
                TakeEpisodeOutcome::Pinned => {
                    let mut users = self
                        .published_config()
                        .await
                        .map(|p| p.sequences.using_episode(id))
                        .unwrap_or_default();
                    if users.is_empty() {
                        users.push("pending_save".to_string());
                    }
                    return Err(ArmError::detailed(
                        409,
                        "IN_USE",
                        format!("Episode '{id}' is used by {} sequence(s)", users.len()),
                        serde_json::json!({"sequences": users}),
                    ));
                }
                TakeEpisodeOutcome::SequenceRevisionChanged => continue,
            }
        }
    }

    /// Linearizably verifies episode `id` is unreferenced (saved, running, or reserved) on the
    /// live owner and removes it from the `EpisodeStore` catalog. Returns `Ok(true)` if removed,
    /// `Ok(false)` if absent, or `Err(409 IN_USE)` if referenced or pinned by a sequence save.
    pub async fn take_episode_for_delete(&self, id: &str) -> Result<bool, ArmError> {
        self.take_episode_for_delete_claim(id)
            .await
            .map(|opt| opt.is_some())
    }

    /// Linearizably verifies every episode in `dataset` is unreferenced (saved, running, or
    /// reserved) and no recording/import pins `dataset`, then atomically removes all of them from
    /// the `EpisodeStore` catalog while returning their deletion claim tokens and a
    /// [`DatasetDeleteGuard`] blocking new pins.
    pub async fn take_dataset_episodes_for_delete(
        &self,
        dataset: &str,
    ) -> Result<(Vec<(String, u64)>, crate::recording::store::DatasetDeleteGuard), ArmError> {
        use crate::recording::store::TakeDatasetOutcome;
        loop {
            let rev0 = self.sequences_revision();
            let store = self.try_episode_store().await?;
            let ids = store.episodes_of(dataset);
            for id in &ids {
                self.check_episode_delete_allowed(id).await?;
            }
            match store.take_dataset_if_unpinned_and_rev_matches(
                dataset,
                &ids,
                &self.sequences_revision,
                rev0,
            ) {
                TakeDatasetOutcome::Removed(taken, guard) => return Ok((taken, guard)),
                TakeDatasetOutcome::DatasetRecordingBusy => {
                    return Err(ArmError::detailed(
                        409,
                        "RECORDER_BUSY",
                        "a recording into this dataset is running",
                        serde_json::json!({}),
                    ));
                }
                TakeDatasetOutcome::Pinned(pinned_id) => {
                    let mut users = self
                        .published_config()
                        .await
                        .map(|p| p.sequences.using_episode(&pinned_id))
                        .unwrap_or_default();
                    if users.is_empty() {
                        users.push("pending_save".to_string());
                    }
                    return Err(ArmError::detailed(
                        409,
                        "IN_USE",
                        format!("Episode '{pinned_id}' is used by {} sequence(s)", users.len()),
                        serde_json::json!({"sequences": users}),
                    ));
                }
                TakeDatasetOutcome::SequenceRevisionChanged => continue,
            }
        }
    }

    /// Current ownership mode (`OWNER_LEGACY`, `OWNER_TRANSFERRING`, `OWNER_EXECUTOR`, `OWNER_FAILED`).
    pub fn owner_mode(&self) -> u8 {
        self.owner_mode.load(Ordering::Acquire)
    }

    /// Configured control frequency (Hz, immutable after startup, lock-free).
    pub fn control_frequency_hz(&self) -> u32 {
        self.control_frequency_hz
    }

    /// Lock-free current stop generation (bumped under the owner lock on Stop).
    pub fn stop_generation(&self) -> u64 {
        self.stop_gen.load(Ordering::SeqCst)
    }

    /// Lock-free current E-stop / safety epoch id.
    pub fn estop_epoch(&self) -> u64 {
        self.estop_epoch.load(Ordering::SeqCst)
    }

    /// Lock-free mirror of the active lease generation (`0` when no lease is held).
    pub fn lease_generation(&self) -> u64 {
        self.lease_gen_mirror.load(Ordering::SeqCst)
    }

    /// Lock-free admission stamp captured ONCE at request entry (WS reader or REST entry).
    pub fn capture_admission_stamp(&self) -> AdmissionStamp {
        AdmissionStamp {
            stop_gen: self.stop_generation(),
            estop_epoch: self.estop_epoch(),
            lease_gen: self.lease_generation(),
            connection_id: 0,
            request_id: next_admission_request_id(),
        }
    }

    /// Human-readable ownership mode name exposed in `GET /api/v1/diagnostics/tick`.
    pub fn owner_mode_name(&self) -> &'static str {
        match self.owner_mode() {
            OWNER_LEGACY => "legacy",
            OWNER_TRANSFERRING => "transferring",
            OWNER_EXECUTOR => "executor",
            OWNER_FAILED => "failed",
            _ => "unknown",
        }
    }

    /// Effective control-loop owner (`Legacy`, `Transferring`, `Executor`, or `Failed`, lock-free).
    pub fn effective_owner(&self) -> crate::model::EffectiveOwner {
        match self.owner_mode() {
            OWNER_EXECUTOR => crate::model::EffectiveOwner::Executor,
            OWNER_TRANSFERRING => crate::model::EffectiveOwner::Transferring,
            OWNER_FAILED => crate::model::EffectiveOwner::Failed,
            _ => crate::model::EffectiveOwner::Legacy,
        }
    }

    /// Why the daemon is running under its current effective owner (lock-free).
    pub fn owner_reason(&self) -> crate::model::OwnerReason {
        crate::model::OwnerReason::from_u8(self.owner_reason.load(Ordering::Acquire))
    }

    /// Records the startup owner selection reason before ownership transfer or after a recoverable
    /// DRV-F1 handback to legacy.
    pub async fn set_owner_reason(&self, reason: crate::model::OwnerReason) {
        self.owner_reason.store(reason as u8, Ordering::Release);
        if self.owner_mode() == OWNER_LEGACY {
            let mut inner = self.inner.write().await;
            if !inner.detached {
                inner.owner_reason = reason;
            }
        }
    }

    /// Attaches the legacy periodic control loop's [`ExecutorStats`] so `GET /api/v1/diagnostics/tick`
    /// reports `skipped_releases`, monotonic release peaks/thresholds, and single-completion publication
    /// into [`LockFreeTickStats`] in Legacy mode.
    pub fn attach_legacy_loop_stats(&self, stats: Arc<crate::rt_core::executor::ExecutorStats>) {
        stats.attach_legacy_tick_ring(Arc::clone(&self.tick_stats));
        *self.legacy_loop_stats.lock().unwrap_or_else(|e| e.into_inner()) = Some(stats);
    }

    /// Signals stop on the legacy periodic control loop, recording the monotonic shutdown timestamp
    /// and waking Linux futex sleep when legacy loop stats are attached.
    pub fn signal_legacy_stop(&self, stop: &AtomicBool) {
        let stats = self.legacy_loop_stats.lock().unwrap_or_else(|e| e.into_inner()).clone();
        if let Some(stats) = stats {
            stats.signal_stop(stop);
        } else {
            stop.store(true, Ordering::SeqCst);
        }
    }

    /// Handle to the synchronous RT executor when ownership has transferred.
    pub fn executor_handle(&self) -> Option<crate::rt_core::executor::RtExecutorHandle> {
        let slot = self.owner.lock().unwrap_or_else(|e| e.into_inner());
        match &*slot {
            OwnerSlot::Executor(h) => Some(h.clone()),
            _ => None,
        }
    }

    /// Re-publishes the revision-tagged off-thread [`ActionPrepEnv`] snapshot into [`StateHub`]
    /// from the Legacy owner lock (no-op in Executor mode, where config mutations update `StateHub`).
    pub async fn refresh_prep_env(&self) {
        if self.owner_mode() != OWNER_LEGACY {
            return;
        }
        let inner = self.inner.read().await;
        if !inner.detached {
            self.hub.update_prep_env(Arc::new(
                crate::rt_core::requests::actions::ActionPrepEnv::from_inner(&inner),
            ));
            self.hub.set_service_identity(Arc::new(
                crate::rt_core::publish::ServiceIdentity::from_inner(&inner),
            ));
        }
    }

    fn check_legacy_under_guard(&self, inner: &SupervisorInner) -> Result<(), ArmError> {
        let mode = self.owner_mode.load(Ordering::Acquire);
        if !inner.detached && mode == OWNER_LEGACY && !self.has_detached_safe_hold() {
            Ok(())
        } else if mode == OWNER_EXECUTOR {
            Err(owner_transferred())
        } else {
            Err(executor_unavailable())
        }
    }

    fn drain_diag(&self) {
        let sink = self.sinks.lock().unwrap_or_else(|e| e.into_inner()).clone();
        if let Some(s) = sink {
            s.drain_diag(&self.tick_stats);
        }
    }

    /// Transfers ownership of `SupervisorInner` (`ArmCore` + bus driver) once at startup
    /// into the synchronous RT executor OS thread.
    pub async fn start_executor(
        &self,
        cfg: crate::rt_core::executor::ExecutorConfig,
    ) -> Result<crate::rt_core::executor::RtExecutorHandle, ArmError> {
        self.start_executor_with_hooks(cfg, crate::rt_core::executor::PersistTestHooks::default()).await
    }

    #[doc(hidden)]
    pub async fn start_executor_with_hooks(
        &self,
        cfg: crate::rt_core::executor::ExecutorConfig,
        hooks: crate::rt_core::executor::PersistTestHooks,
    ) -> Result<crate::rt_core::executor::RtExecutorHandle, ArmError> {
        self.ensure_dispatcher()?;
        let saved_legacy_stop = {
            let mut slot = self.owner.lock().unwrap_or_else(|e| e.into_inner());
            if !matches!(*slot, OwnerSlot::Legacy) {
                return Err(ArmError::Rejected {
                    status: 409,
                    code: "OWNER_ALREADY_TRANSFERRED".into(),
                    message: "RT executor ownership can only be transferred once from Legacy mode".into(),
                });
            }
            *slot = OwnerSlot::Transferring;
            let mut w = self.active_writer.lock().unwrap_or_else(|e| e.into_inner());
            let prev_stop = match &*w {
                WriterEndpoint::Legacy { control_stop, .. } => control_stop.clone(),
                _ => None,
            };
            *w = WriterEndpoint::Transferring;
            drop(w);
            self.owner_mode.store(OWNER_TRANSFERRING, Ordering::Release);
            prev_stop
        };
        let mut rollback = TransferGuard {
            sup: self,
            armed: true,
            saved_legacy_stop,
        };

        // The single `.await` point in handoff: if cancelled here, `TransferGuard` rolls back to `Legacy`.
        let mut guard = self.inner.write().await;

        let restore_legacy = |rollback: &mut TransferGuard<'_>| {
            {
                let mut slot = self.owner.lock().unwrap_or_else(|e| e.into_inner());
                if matches!(*slot, OwnerSlot::Transferring) {
                    *slot = OwnerSlot::Legacy;
                    self.owner_mode.store(OWNER_LEGACY, Ordering::Release);
                }
            }
            {
                let mut w = self.active_writer.lock().unwrap_or_else(|e| e.into_inner());
                if matches!(*w, WriterEndpoint::Transferring) {
                    *w = WriterEndpoint::Legacy {
                        control_stop: rollback.saved_legacy_stop.take(),
                        safe_hold: Arc::clone(&self.legacy_safe_hold),
                    };
                }
            }
            rollback.armed = false;
        };

        // Zero `.await` points below this line: drain all socket-close disconnects queued while
        // the write lock was held or during `OWNER_TRANSFERRING` BEFORE checking transfer state,
        // seeding `ConnLifecycleClient`, or spawning RT, so RT never inherits a stale connection
        // or lease.
        if !guard.detached {
            let _ = self.drain_pending_disconnects_under_guard(&mut guard, None);
            guard.purge_closed_live_connections();
        }
        if guard.detached
            || guard.calibration_busy
            || guard.motor_zero_busy
            || guard.zero_check_persisting.is_some()
            || guard.gravity_comp.is_some()
            || guard.macro_run.is_some()
            || guard.mit_active()
            || guard.mit.revoke_pending
        {
            restore_legacy(&mut rollback);
            return Err(ArmError::Rejected {
                status: 409,
                code: "TRANSFER_BLOCKED".into(),
                message: "Cannot transfer ownership while calibration, zero_check persistence, motor_zero, gravity compensation, macro action, or MIT tracking is active".into(),
            });
        }
        #[cfg(feature = "policy-runtime")]
        if guard.policy_loading || guard.policy_run.is_some() {
            restore_legacy(&mut rollback);
            return Err(ArmError::Rejected {
                status: 409,
                code: "TRANSFER_BLOCKED".into(),
                message: "Cannot transfer ownership while policy runtime is active or loading".into(),
            });
        }
        if crate::mit::mit_joint_mask(&guard.config) != 0 {
            restore_legacy(&mut rollback);
            return Err(ArmError::Rejected {
                status: 503,
                code: "UNSUPPORTED_RT_CONFIG".into(),
                message: "MIT-configured profiles require synchronous qualification/handover and are not supported under synchronous RT executor step 1".into(),
            });
        }
        if guard.config.dof > crate::rt_core::mailbox::MAX_DOF {
            restore_legacy(&mut rollback);
            return Err(ArmError::Rejected {
                status: 503,
                code: "UNSUPPORTED_RT_CONFIG".into(),
                message: format!(
                    "Profile DOF {} exceeds synchronous RT executor mailbox limit {}; run under legacy owner",
                    guard.config.dof,
                    crate::rt_core::mailbox::MAX_DOF
                ),
            });
        }
        // Flush any legacy E-stop acks already applied before handoff so waiting callers
        // receive their exact recorded (state, epoch) instead of stalling after transfer,
        // and drop any legacy retired fault Arcs off-thread before transferring ownership.
        // Driver preflight (`position_limits` / `supports_rt_executor`) executes inside
        // `armd-control`'s bounded `StartupSlot` transaction so no driver callback can stall
        // or unwind on the caller thread while `SupervisorLock` is held.
        Self::flush_legacy_estop_acks_into(&self.estop_reg, &mut guard);
        guard.safety.drain_retired_state_arcs_off_thread();
        guard.tracking.normalize_spares_off_thread();
        guard.prepare_workspace_eval_bufs();
        guard.prepare_park_release_spare();
        guard.refresh_schema_cache();

        let initial_gen = self.inner.generation();
        let candidate_pub_cfg = crate::rt_core::requests::config::PublishedConfig::from_inner(&guard);
        let staged_hover_jobs = guard.hover_jobs.clone();
        let staged_service_identity = Arc::new(
            crate::rt_core::publish::ServiceIdentity::from_published_config(
                guard.core.id(),
                cfg.boot,
                &candidate_pub_cfg,
            ),
        );
        let shell = SupervisorInner::detached_shell(
            &guard.config,
            self.estop_state.clone(),
            self.stop_gen.clone(),
            self.lease_gen_mirror.clone(),
            self.closed_bitset.clone(),
            self.atomic_fenced_lease_gen.clone(),
            self.pending_disconnect_hold.clone(),
        );
        // Clone the preallocated legacy waiter slots and transform any in-flight LegacyWs torque
        // transition BEFORE moving `real` into the executor:
        // - LegacyWs enable -> DetachedCancel (`Cancelling`) so the executor never retries or arms
        //   an abandoned legacy WS enable and cleanly calls `drv.abort_enable()`.
        // - LegacyWs disable -> Detached so dispatched/protective hardware disables complete cleanly.
        // Waiters are settled as `OwnerTransferred` ONLY AFTER `spawn_executor` commits (or fails
        // unrecoverably); on rollback (`Recoverable` or `into_exclusive` failure), the original
        // transition and waiter remain intact.
        let handoff_slots = guard.legacy_torque_slots.clone();
        let saved_legacy_transition = guard.torque_transition;
        match guard.torque_transition {
            Some(driver_transitions::TorqueTransition::Enable(mut reducer))
                if matches!(reducer.origin, driver_transitions::EnableOrigin::LegacyWs { .. }) =>
            {
                reducer.origin = driver_transitions::EnableOrigin::DetachedCancel;
                reducer.phase = driver_transitions::EnableReducerPhase::Cancelling;
                reducer.authority = None;
                guard.torque_transition = Some(driver_transitions::TorqueTransition::Enable(reducer));
            }
            Some(driver_transitions::TorqueTransition::Disable {
                origin: driver_transitions::DisableOrigin::LegacyWs { deadline, .. },
                kind,
            }) => {
                // Preserve `Some(deadline)` across owner handoff so an undispatched disable still
                // expires cleanly on the new owner without transmitting past its deadline; once
                // dispatched (or protective), the new owner clears the deadline and completes it.
                let handoff_dl = if matches!(kind, crate::driver::DisableKind::DisableProtective { .. })
                    || guard.torque_intent == driver_transitions::TorqueIntent::Off
                {
                    None
                } else {
                    Some(deadline)
                };
                guard.torque_transition = Some(driver_transitions::TorqueTransition::Disable {
                    origin: driver_transitions::DisableOrigin::Detached { deadline: handoff_dl },
                    kind,
                });
            }
            _ => {}
        }
        let mut real = std::mem::replace(&mut *guard, shell);
        let live_ids: Vec<u64> = real.live_connection_ids().collect();
        let seeded_ws_sinks = self.ws_slots.sinks_for_live_ids(&live_ids);
        if let Some(slot) = real.driver.take() {
            match slot.into_exclusive() {
                Ok(exclusive) => real.driver = Some(exclusive),
                Err((legacy_slot, reason)) => {
                    real.driver = Some(legacy_slot);
                    *guard = real;
                    guard.torque_transition = saved_legacy_transition;
                    restore_legacy(&mut rollback);
                    return Err(ArmError::Rejected {
                        status: 503,
                        code: "UNSUPPORTED_RT_DRIVER".into(),
                        message: format!("Cannot transfer ownership: {reason}"),
                    });
                }
            }
        }
        #[cfg(not(target_arch = "wasm32"))]
        {
            real.flush_torque_shadow();
            real.torque_shadow
                .set_owner(crate::torque::shadow::ShadowOwner::Executor);
            if let Err(e) = self.torque_shadow.start_worker() {
                tracing::warn!("Failed to start torque shadow worker thread on executor handoff: {e}");
            }
        }

        match crate::rt_core::executor::spawn_executor(
            real,
            cfg,
            initial_gen,
            Arc::clone(&self.config_write_mutex),
            Arc::clone(&self.published_config),
            Arc::clone(&self.estop_reg),
            Arc::clone(&self.tick_stats),
            Arc::clone(&self.control_sched),
            Arc::clone(&self.control_period_us),
            Arc::clone(&self.internal_fault_lane),
            hooks,
        ) {
            Ok((handle, sinks, ready_payload, startup_gate)) => {
                // Single startup activation barrier (R5 Major 2 / M2):
                // Commit staged hub snapshots, observation prewarm, scheduler readiness,
                // published_config, sinks, and `OWNER_EXECUTOR` atomically strictly OUTSIDE the
                // StartupGate mutex and strictly BEFORE releasing `armd-control` to Release #1.
                if Instant::now() >= startup_gate.deadline() {
                    startup_gate.mark_aborted();
                    let mut any_settled = false;
                    for slot in &handoff_slots {
                        any_settled |= slot.settle_owner_transferred();
                    }
                    self.published_config.set_available(false);
                    {
                        let mut slot = self.owner.lock().unwrap_or_else(|e| e.into_inner());
                        *slot = OwnerSlot::Failed;
                        self.owner_mode.store(OWNER_FAILED, Ordering::Release);
                    }
                    {
                        let mut w = self.active_writer.lock().unwrap_or_else(|e| e.into_inner());
                        *w = WriterEndpoint::DetachedSafeHold {
                            safe_hold: handle.safe_hold_control(),
                            control_stop: Arc::new(AtomicBool::new(true)),
                        };
                    }
                    rollback.armed = false;
                    drop(guard);
                    if any_settled {
                        self.legacy_torque_notify.notify_waiters();
                    }
                    return Err(ArmError::Internal(
                        "RT executor startup timed out before activation barrier".into(),
                    ));
                }
                let mut any_settled = false;
                for slot in &handoff_slots {
                    any_settled |= slot.settle_owner_transferred();
                }
                handle.seed_connection_reply_sinks(seeded_ws_sinks);
                self.hub.set_motion_config(ready_payload.staged_motion_cfg);
                self.hub.update_prep_env(ready_payload.staged_prep_env);
                self.hub.set_service_identity(staged_service_identity);
                self.hub.install_prewarm_template_and_front(
                    ready_payload.staged_obs_template,
                    ready_payload.staged_front_obs,
                );
                *self
                    .control_sched
                    .lock()
                    .unwrap_or_else(|e| e.into_inner()) = Some(ready_payload.staged_sched);
                if let Some(readiness) = ready_payload.staged_readiness {
                    crate::rt_core::sched::set_readiness(readiness);
                }
                self.published_config.publish(candidate_pub_cfg, initial_gen);
                *self
                    .executor_hover_jobs
                    .lock()
                    .unwrap_or_else(|e| e.into_inner()) = staged_hover_jobs;
                *self.sinks.lock().unwrap_or_else(|e| e.into_inner()) = Some(sinks);
                self.executor_base_gen.store(initial_gen, Ordering::Release);
                {
                    let mut slot = self.owner.lock().unwrap_or_else(|e| e.into_inner());
                    *slot = OwnerSlot::Executor(handle.clone());
                    self.owner_mode.store(OWNER_EXECUTOR, Ordering::Release);
                }
                {
                    let mut w = self.active_writer.lock().unwrap_or_else(|e| e.into_inner());
                    *w = WriterEndpoint::Executor(handle.clone());
                }
                if !startup_gate.mark_activated() {
                    // `armd-control` already timed out waiting for activation: roll owner to
                    // `Failed` and record detached SAFE-HOLD endpoint.
                    self.published_config.set_available(false);
                    {
                        let mut slot = self.owner.lock().unwrap_or_else(|e| e.into_inner());
                        *slot = OwnerSlot::Failed;
                        self.owner_mode.store(OWNER_FAILED, Ordering::Release);
                    }
                    {
                        let mut w = self.active_writer.lock().unwrap_or_else(|e| e.into_inner());
                        *w = WriterEndpoint::DetachedSafeHold {
                            safe_hold: handle.safe_hold_control(),
                            control_stop: Arc::new(AtomicBool::new(true)),
                        };
                    }
                    rollback.armed = false;
                    drop(guard);
                    return Err(ArmError::Internal(
                        "RT executor startup activation expired".into(),
                    ));
                }
                rollback.armed = false;
                drop(guard);
                if any_settled {
                    self.legacy_torque_notify.notify_waiters();
                }
                // Forward any socket-close disconnects queued in the tiny window between draining
                // `guard` and publishing `OWNER_EXECUTOR` directly to the new RT owner.
                self.forward_pending_disconnects_to_executor(&handle);
                self.hub.wake();
                Ok(handle)
            }
            Err(crate::rt_core::executor::SpawnExecutorError::Recoverable {
                mut core,
                unsupported_reason,
                msg,
            }) => {
                if let Some(mut slot) = core.driver.take() {
                    if let Some(drv) = slot.as_exclusive_mut() {
                        drv.set_rt_mode(false);
                    }
                    core.driver = Some(slot.into_legacy(Arc::clone(&self.driver_lock_attempts)));
                }
                *guard = *core;
                guard.torque_transition = saved_legacy_transition;
                #[cfg(not(target_arch = "wasm32"))]
                guard
                    .torque_shadow
                    .set_owner(crate::torque::shadow::ShadowOwner::Legacy);
                let _ = self.drain_pending_disconnects_under_guard(&mut guard, None);
                guard.purge_closed_live_connections();
                restore_legacy(&mut rollback);
                drop(guard);
                self.try_drain_pending_disconnects_legacy();
                if let Some(reason) = unsupported_reason {
                    Err(ArmError::Rejected {
                        status: 503,
                        code: "UNSUPPORTED_RT_DRIVER".into(),
                        message: format!("Cannot transfer ownership: {reason}"),
                    })
                } else {
                    Err(ArmError::Internal(msg))
                }
            }
            Err(crate::rt_core::executor::SpawnExecutorError::Fatal(msg)) => {
                let mut any_settled = false;
                for slot in &handoff_slots {
                    any_settled |= slot.settle_owner_transferred();
                }
                self.published_config.set_available(false);
                {
                    let mut slot = self.owner.lock().unwrap_or_else(|e| e.into_inner());
                    *slot = OwnerSlot::Failed;
                    self.owner_mode.store(OWNER_FAILED, Ordering::Release);
                }
                {
                    // `Fatal` only fires after `armd-control` confirmed disarmed/driverless and
                    // dropped `core`; publish a terminal exited endpoint so `active_writer` does
                    // not remain stuck in `Transferring`.
                    let exited_sh = Arc::new(crate::rt_core::safe_hold::SafeHoldControl::new());
                    exited_sh.record_process_exit_outcome_lockfree(&PanicDisableOutcome::NoDriver);
                    exited_sh.mark_exited();
                    let mut w = self.active_writer.lock().unwrap_or_else(|e| e.into_inner());
                    *w = WriterEndpoint::DetachedSafeHold {
                        safe_hold: exited_sh,
                        control_stop: Arc::new(AtomicBool::new(true)),
                    };
                }
                rollback.armed = false;
                drop(guard);
                if any_settled {
                    self.legacy_torque_notify.notify_waiters();
                }
                Err(ArmError::Internal(msg))
            }
            Err(crate::rt_core::executor::SpawnExecutorError::FatalDetachedSafeHold {
                msg,
                safe_hold,
                control_stop,
            }) => {
                let mut any_settled = false;
                for slot in &handoff_slots {
                    any_settled |= slot.settle_owner_transferred();
                }
                self.published_config.set_available(false);
                {
                    let mut slot = self.owner.lock().unwrap_or_else(|e| e.into_inner());
                    *slot = OwnerSlot::Failed;
                    self.owner_mode.store(OWNER_FAILED, Ordering::Release);
                }
                {
                    let mut w = self.active_writer.lock().unwrap_or_else(|e| e.into_inner());
                    *w = WriterEndpoint::DetachedSafeHold {
                        safe_hold,
                        control_stop,
                    };
                }
                rollback.armed = false;
                drop(guard);
                if any_settled {
                    self.legacy_torque_notify.notify_waiters();
                }
                Err(ArmError::Internal(msg))
            }
        }
    }

    /// Hands ownership cleanly from `OWNER_EXECUTOR` back to `OWNER_LEGACY` when the driver is
    /// already confirmed physically disarmed. Refuses energized handback without a prepared live
    /// periodic legacy receiver — energized callers must use [`Self::handback_to_legacy_with_live_loop`]
    /// so an energized arm is never left without a periodic writer (DRV-F1 B2).
    pub async fn handback_to_legacy(&self, timeout: Duration) -> Result<(), ArmError> {
        self.handback_to_legacy_inner(timeout, None).await
    }

    async fn handback_to_legacy_inner(
        &self,
        timeout: Duration,
        live_receiver: Option<(
            &Arc<(std::sync::Mutex<Option<bool>>, std::sync::Condvar)>,
            &Arc<AtomicBool>,
        )>,
    ) -> Result<(), ArmError> {
        let deadline = Instant::now() + timeout;
        let handle = {
            let mut slot = self.owner.lock().unwrap_or_else(|e| e.into_inner());
            match std::mem::replace(&mut *slot, OwnerSlot::Transferring) {
                OwnerSlot::Executor(h) => {
                    self.owner_mode.store(OWNER_TRANSFERRING, Ordering::Release);
                    h
                }
                other => {
                    *slot = other;
                    return Err(ArmError::Rejected {
                        status: 409,
                        code: "OWNER_NOT_EXECUTOR".into(),
                        message: "Handback requires active RT executor ownership".into(),
                    });
                }
            }
        };

        struct HandbackGuard<'a> {
            sup: &'a ArmSupervisor,
            handle: Option<crate::rt_core::executor::RtExecutorHandle>,
        }
        impl Drop for HandbackGuard<'_> {
            fn drop(&mut self) {
                if let Some(h) = self.handle.take() {
                    let mut slot = self.sup.owner.lock().unwrap_or_else(|e| e.into_inner());
                    if matches!(*slot, OwnerSlot::Transferring) {
                        *slot = OwnerSlot::Executor(h);
                        self.sup.owner_mode.store(OWNER_EXECUTOR, Ordering::Release);
                    }
                }
            }
        }
        let mut hb_guard = HandbackGuard {
            sup: self,
            handle: Some(handle.clone()),
        };

        // Acquire the legacy shell write lock BEFORE signaling `armd-control` to stop.
        // If cancelled or timed out here, `HandbackGuard` restores `OWNER_EXECUTOR` cleanly.
        let rem = deadline.saturating_duration_since(Instant::now());
        if rem.is_zero() {
            return Err(ArmError::Rejected {
                status: 503,
                code: "HANDBACK_TIMED_OUT".into(),
                message: "Handback deadline expired before acquiring legacy shell".into(),
            });
        }
        let mut guard = match tokio::time::timeout(rem, self.inner.write()).await {
            Ok(g) => g,
            Err(_) => {
                return Err(ArmError::Rejected {
                    status: 503,
                    code: "HANDBACK_TIMED_OUT".into(),
                    message: "Handback timed out waiting for legacy shell lock".into(),
                });
            }
        };

        // Reject bare energized handback without a prepared live receiver BEFORE signaling stop (B2).
        if live_receiver.is_none() && !handle.shutdown_ready().unwrap_or(false) {
            return Err(ArmError::Rejected {
                status: 409,
                code: "HANDBACK_REQUIRES_LIVE_RECEIVER".into(),
                message: "Energized handback requires a prepared live legacy receiver (use handback_to_legacy_with_live_loop)".into(),
            });
        }

        // Zero `.await` points below: commit handback request on `armd-control` within the SAME
        // deadline, carrying `live_receiver.is_some()` to the owner-side commit point (DRV-F1 B4).
        match handle.take_handback_core_until(deadline, live_receiver.is_some()) {
            Ok(mut core) => {
                if let Some(slot) = core.driver.take() {
                    core.driver = Some(slot.into_legacy(Arc::clone(&self.driver_lock_attempts)));
                }
                core.detached = false;
                core.rt_executor_owned = false;
                core.internal_fault_lane = Arc::clone(&self.internal_fault_lane);
                #[cfg(not(target_arch = "wasm32"))]
                {
                    core.flush_torque_shadow();
                    core.torque_shadow
                        .set_owner(crate::torque::shadow::ShadowOwner::Legacy);
                    self.torque_shadow.wake();
                }
                *guard = *core;
                guard.hover_jobs = self
                    .executor_hover_jobs
                    .lock()
                    .unwrap_or_else(|e| e.into_inner())
                    .clone();
                let _ = self.drain_pending_disconnects_under_guard(&mut guard, None);
                guard.purge_closed_live_connections();
                *self.sinks.lock().unwrap_or_else(|e| e.into_inner()) = None;
                {
                    let mut slot = self.owner.lock().unwrap_or_else(|e| e.into_inner());
                    *slot = OwnerSlot::Legacy;
                    self.owner_mode.store(OWNER_LEGACY, Ordering::Release);
                }
                {
                    let mut w = self.active_writer.lock().unwrap_or_else(|e| e.into_inner());
                    *w = WriterEndpoint::Legacy {
                        control_stop: live_receiver.map(|(_, stop)| Arc::clone(stop)),
                        safe_hold: Arc::clone(&self.legacy_safe_hold),
                    };
                }
                hb_guard.handle = None;
                drop(guard);
                // Release the pre-spawned live legacy receiver IMMEDIATELY after dropping `guard`
                // and BEFORE running bounded worker teardown so energized holds continue with
                // minimal inter-frame gap (B2).
                if let Some((ready, _)) = live_receiver {
                    let (lock, cv) = &**ready;
                    *lock.lock().unwrap_or_else(|e| e.into_inner()) = Some(true);
                    cv.notify_all();
                }
                handle.finish_handback_cleanup_until(deadline);
                self.try_drain_pending_disconnects_legacy();
                Ok(())
            }
            Err(crate::rt_core::executor::HandbackFailure::TimedOutSafeHold) => {
                self.published_config.set_available(false);
                {
                    let mut slot = self.owner.lock().unwrap_or_else(|e| e.into_inner());
                    *slot = OwnerSlot::Failed;
                    self.owner_mode.store(OWNER_FAILED, Ordering::Release);
                }
                {
                    let mut w = self.active_writer.lock().unwrap_or_else(|e| e.into_inner());
                    *w = WriterEndpoint::DetachedSafeHold {
                        safe_hold: handle.safe_hold_control(),
                        control_stop: Arc::new(AtomicBool::new(true)),
                    };
                }
                hb_guard.handle = None;
                drop(guard);
                Err(ArmError::Rejected {
                    status: 503,
                    code: "HANDBACK_STALLED_SAFE_HOLD".into(),
                    message: "Energized handback timed out; exclusive driver retained in SAFE-HOLD"
                        .into(),
                })
            }
            Err(crate::rt_core::executor::HandbackFailure::ExecutorExited) => {
                self.published_config.set_available(false);
                {
                    let mut slot = self.owner.lock().unwrap_or_else(|e| e.into_inner());
                    *slot = OwnerSlot::Failed;
                    self.owner_mode.store(OWNER_FAILED, Ordering::Release);
                }
                hb_guard.handle = None;
                drop(guard);
                Err(ArmError::Rejected {
                    status: 503,
                    code: "EXECUTOR_STOPPED".into(),
                    message: "RT executor exited before handback completed".into(),
                })
            }
        }
    }

    /// Starts a live legacy control loop parked on a ready gate, executes energized handback,
    /// and unparks the legacy loop immediately after restoring `self.inner` and publishing
    /// `OWNER_LEGACY` (BEFORE worker cleanup finishes — B2). On handback failure, cancels the
    /// parked thread cleanly so no second writer ever runs.
    pub async fn handback_to_legacy_with_live_loop(
        self: &Arc<Self>,
        timeout: Duration,
        period: Duration,
    ) -> Result<(Arc<AtomicBool>, std::thread::JoinHandle<()>), ArmError> {
        let ready = Arc::new((std::sync::Mutex::new(Option::<bool>::None), std::sync::Condvar::new()));
        let control_stop = Arc::new(AtomicBool::new(false));
        let stats = Arc::new(crate::rt_core::executor::ExecutorStats::default());
        let sup_bg = Arc::clone(self);
        let ready_bg = Arc::clone(&ready);
        let stop_bg = Arc::clone(&control_stop);
        let stats_bg = Arc::clone(&stats);
        let runtime = tokio::runtime::Handle::current();
        let jh = std::thread::Builder::new()
            .name("armd-control-legacy".into())
            .spawn(move || {
                let (lock, cv) = &*ready_bg;
                let proceed = {
                    let mut g = lock.lock().unwrap_or_else(|e| e.into_inner());
                    while g.is_none() {
                        g = cv.wait(g).unwrap_or_else(|e| e.into_inner());
                    }
                    g.unwrap_or(false)
                };
                if !proceed {
                    return;
                }
                sup_bg.attach_legacy_loop_stats(stats_bg.clone());
                sup_bg.run_legacy_control_loop_blocking(period, stop_bg, stats_bg, runtime, None);
            })
            .map_err(|e| ArmError::Internal(format!("failed to prepare legacy receiver thread: {e}")))?;

        match self
            .handback_to_legacy_inner(timeout, Some((&ready, &control_stop)))
            .await
        {
            Ok(()) => Ok((control_stop, jh)),
            Err(e) => {
                {
                    let (lock, cv) = &*ready;
                    *lock.lock().unwrap_or_else(|e| e.into_inner()) = Some(false);
                    cv.notify_all();
                }
                let _ = jh.join();
                Err(e)
            }
        }
    }

    pub fn config_write_lock(&self) -> Arc<tokio::sync::Mutex<()>> {
        Arc::clone(&self.config_write_mutex)
    }

    pub fn published_config_hub(&self) -> &Arc<crate::rt_core::requests::config::PublishedConfigHub> {
        &self.published_config
    }

    /// Filters `PublishedConfig::sequences.pins` on `OWNER_EXECUTOR` against the live published
    /// `StateHub` action state so stale sequence pins are never exposed once the owning action has
    /// reached a terminal state (even before async `cleanup()` clears `pins`).
    fn filter_executor_published_config(
        &self,
        cfg: Arc<crate::rt_core::requests::config::PublishedConfig>,
    ) -> Arc<crate::rt_core::requests::config::PublishedConfig> {
        if cfg.sequences.pins.is_none() {
            return cfg;
        }
        let running_action_id = self
            .hub()
            .latest()
            .and_then(|s| s.obs.action.as_ref().filter(|a| a.is_running()).map(|a| a.id));
        if cfg.sequences.active_pins(running_action_id).is_some() {
            return cfg;
        }
        let mut filtered = (*cfg).clone();
        filtered.sequences.pins = None;
        Arc::new(filtered)
    }

    /// Returns the latest published configuration snapshot without touching `SupervisorLock`
    /// in `OWNER_EXECUTOR` mode. Fails closed with `503 CONFIG_UNAVAILABLE` if ownership is
    /// transitioning or failed.
    pub async fn published_config(
        &self,
    ) -> Result<Arc<crate::rt_core::requests::config::PublishedConfig>, ArmError> {
        match self.owner_mode() {
            OWNER_EXECUTOR => {
                let Some(handle) = self.executor_handle() else {
                    return Err(crate::rt_core::requests::config::config_unavailable());
                };
                if handle.is_exited() {
                    return Err(crate::rt_core::requests::config::config_unavailable());
                }
                let cfg = self
                    .published_config
                    .latest()
                    .ok_or_else(crate::rt_core::requests::config::config_unavailable)?;
                Ok(self.filter_executor_published_config(cfg))
            }
            OWNER_LEGACY => {
                let current_gen = self.inner.generation();
                let (cached, cached_gen) = self.published_config.latest_with_gen();
                if cached_gen == current_gen {
                    return Ok(cached);
                }
                let inner = self.inner.read().await;
                if inner.detached {
                    drop(inner);
                    if self.owner_mode() == OWNER_EXECUTOR {
                        let Some(handle) = self.executor_handle() else {
                            return Err(crate::rt_core::requests::config::config_unavailable());
                        };
                        if handle.is_exited() {
                            return Err(crate::rt_core::requests::config::config_unavailable());
                        }
                        let cfg = self
                            .published_config
                            .latest()
                            .ok_or_else(crate::rt_core::requests::config::config_unavailable)?;
                        return Ok(self.filter_executor_published_config(cfg));
                    }
                    return Err(crate::rt_core::requests::config::config_unavailable());
                }
                let gen = self.inner.generation();
                let snap = crate::rt_core::requests::config::PublishedConfig::from_inner(&inner);
                drop(inner);
                Ok(self.published_config.publish_if_newer(snap, gen))
            }
            _ => Err(crate::rt_core::requests::config::config_unavailable()),
        }
    }

    /// Returns a lock-free handle to `SupervisorInner::control_release_seq_atomic` plus its current
    /// sequence value so off-lock legacy commissioning waiters can detect whether a live 50 Hz
    /// control ticker is actively servicing `service_commissioning_release`.
    #[cfg(not(target_arch = "wasm32"))]
    pub(crate) async fn legacy_tick_seq_counter(&self) -> Option<(Arc<AtomicU64>, u64)> {
        if self.owner_mode() != OWNER_LEGACY {
            return None;
        }
        let inner = self.inner.read().await;
        if inner.detached {
            return None;
        }
        let counter = Arc::clone(&inner.control_release_seq_atomic);
        let cur = counter.load(Ordering::Acquire);
        Some((counter, cur))
    }

    /// Headless fallback stepper for legacy ticked commissioning when no background 50 Hz control
    /// loop is running (mirrors TQ-LOCK headless fallback). Re-verifies under `SupervisorLock::write`
    /// that `control_release_seq == expected_seq`, then runs at most ONE bounded step (`<= 1 ms`,
    /// max 1 TX frame) without double-subtracting publish margin so write-guard holds stay `<= 2 ms`.
    #[cfg(not(target_arch = "wasm32"))]
    pub(crate) async fn step_legacy_commissioning_headless(
        &self,
        op_id: u64,
        expected_seq: u64,
    ) -> (u64, bool) {
        // 1 ms cutoff with max 1 TX frame (no second margin subtraction) keeps SG2002 headless
        // progress non-starving while bounding every SupervisorLock::write hold <= 2 ms.
        const LEGACY_HEADLESS_COMM_BUDGET: Duration = Duration::from_millis(1);
        let mut inner = self.inner.write().await;
        let io_scope = crate::diagnostics::tick::HoldIoScope::enter();
        inner.set_command(crate::mit::TIMEOUT_PATH);
        if inner.detached
            || inner.control_release_seq != expected_seq
            || !inner.commissioning.is_running_op(op_id)
        {
            let seq = inner.control_release_seq;
            inner.set_io_timing(io_scope.finish());
            return (seq, false);
        }
        inner.control_release_seq = inner.control_release_seq.wrapping_add(1).max(1);
        inner
            .control_release_seq_atomic
            .store(inner.control_release_seq, Ordering::Release);
        let seq = inner.control_release_seq;
        if let Some(ref mut slot) = inner.driver {
            let _ = slot.try_with_mut(|drv| drv.begin_control_release(seq));
        }
        let step_now = Instant::now();
        let ctx = crate::rt_core::ops::CommitCtx {
            arm: inner.core.id(),
            boot: crate::rt_core::broker::BootId::process(),
            now: step_now,
            stop_generation: inner.current_stop_gen(),
        };
        let mut sys_now = Instant::now;
        let _ = inner.service_commissioning_step_with_cutoff(
            &ctx,
            step_now + LEGACY_HEADLESS_COMM_BUDGET,
            1,
            Some(1),
            true,
            &mut sys_now,
        );
        inner.flush_torque_shadow();
        inner.set_io_timing(io_scope.finish());
        (seq, true)
    }

    /// Post-tick legacy commissioning scheduler invoked by [`Self::tick_shared`] strictly AFTER
    /// the control tick's own RX/output/publish write guard has dropped.
    ///
    /// - Derives the release cutoff strictly from `release_deadline - comm_margin` (matching
    ///   TQ-LOCK TX deadline separation, never `tick_wall_start + 1 ms`).
    /// - Splits commissioning I/O across short bounded `SupervisorLock::write` guards (`<= 1.2 ms`
    ///   and max 1 TX frame per guard) so even on SG2002 (1.0–1.5 ms RX drain, 0.4–0.6 ms/frame TX)
    ///   EVERY write-guard hold stays strictly `<= 2 ms` and commissioning makes progress every
    ///   release without delaying control releases.
    /// - Bounds total commissioning register I/O to `COMM_MAX_TX_PER_RELEASE` frames per release
    ///   (and at most one `GatherRestEvidence` `0xCC` burst per release), sleeping only OFF-LOCK
    ///   when awaiting an in-flight reply within the remaining release budget.
    #[cfg(not(target_arch = "wasm32"))]
    async fn service_legacy_commissioning_post_tick(
        &self,
        tick_started: Instant,
        release_deadline: Instant,
        comm_margin: Duration,
        tx_budget_dur: Duration,
    ) {
        const OFF_LOCK_REPLY_POLL_INTERVAL: Duration = Duration::from_millis(1);
        const MAX_OFF_LOCK_POLLS_PER_REQ: u8 = 3;
        const MAX_GUARD_STEPS_PER_RELEASE: u8 = 16;

        let Some(comm_release_cap) = release_deadline.checked_sub(comm_margin) else {
            return;
        };
        // Keep off-lock reply polling strictly inside BOTH `release_deadline - comm_margin` AND
        // the driver's per-release TX pass duration so subsequent same-release sends never hit
        // spurious TX-duration backpressure.
        let comm_wait_cap = comm_release_cap.min(
            tick_started + tx_budget_dur.saturating_sub(Duration::from_millis(1)),
        );

        let mut reg_tx_left: u8 = crate::mit::COMM_MAX_TX_PER_RELEASE;
        let mut probe_tx_left: u8 = crate::rt_core::mailbox::MAX_DOF as u8;
        let mut first_step = true;
        let mut wait_polls_for_req: u8 = 0;
        let mut guard_steps: u8 = 0;
        let mut lock_yields: u8 = 0;

        while guard_steps < MAX_GUARD_STEPS_PER_RELEASE {
            if self.owner_mode() != OWNER_LEGACY
                || self.estop_state.is_latched()
                || self.process_exit_requested.load(Ordering::Acquire)
                || self.internal_fault_lane.is_fenced()
            {
                break;
            }
            // Never acquire `SupervisorLock` for optional commissioning once the release cutoff
            // (`release_deadline - comm_margin`) has elapsed.
            if Instant::now() >= comm_release_cap {
                break;
            }
            // Non-blocking acquisition: optional post-tick commissioning must NEVER queue behind
            // another `SupervisorLock` holder and delay the next 50 Hz control release.
            let Ok(mut inner) = self.inner.try_write() else {
                if lock_yields >= 1 || Instant::now() >= comm_release_cap {
                    break;
                }
                lock_yields = lock_yields.saturating_add(1);
                tokio::task::yield_now().await;
                continue;
            };
            lock_yields = 0;
            let progress = {
                let io_scope = crate::diagnostics::tick::HoldIoScope::enter();
                inner.set_command(crate::mit::TIMEOUT_PATH);
                let guard_start = Instant::now();
                if self.owner_mode() != OWNER_LEGACY
                    || guard_start >= comm_release_cap
                    || !inner.legacy_commissioning_eligible()
                {
                    inner.set_io_timing(io_scope.finish());
                    break;
                }
                let ctx = crate::rt_core::ops::CommitCtx {
                    arm: inner.core.id(),
                    boot: crate::rt_core::broker::BootId::process(),
                    now: guard_start,
                    stop_generation: inner.current_stop_gen(),
                };
                // Each guard executes at most 1 commissioning TX frame (keeping guard hold <= 2 ms
                // on SG2002 0.4–0.6 ms/frame TX) while passing the true `comm_release_cap`
                // (`release_deadline - comm_margin`) as the hardware TX/flush cutoff so transient
                // OS jitter never causes false `SentFlushFailed` on non-noop flush transports.
                let step_reg_tx = reg_tx_left.min(1);
                let step_probe_tx = probe_tx_left.min(1);
                let mut sys_now = Instant::now;
                let p = inner.service_commissioning_step_with_cutoff(
                    &ctx,
                    comm_release_cap,
                    step_reg_tx,
                    Some(step_probe_tx),
                    first_step,
                    &mut sys_now,
                );
                inner.flush_torque_shadow();
                inner.set_io_timing(io_scope.finish());
                p
            };
            drop(inner);
            first_step = false;
            guard_steps = guard_steps.saturating_add(1);
            if progress.probe_tx_attempted > 0 {
                probe_tx_left = probe_tx_left.saturating_sub(progress.probe_tx_attempted);
            }
            if progress.reg_tx_attempted > 0 {
                reg_tx_left = reg_tx_left.saturating_sub(progress.reg_tx_attempted);
                wait_polls_for_req = 0;
            }
            if !progress.still_running
                || progress.contended
                || progress.backpressured
                || self.estop_state.is_latched()
                || self.owner_mode() != OWNER_LEGACY
            {
                break;
            }
            let now = Instant::now();
            if now >= comm_release_cap {
                break;
            }
            if progress.rest_probe_pending {
                if probe_tx_left == 0 {
                    break;
                }
                tokio::task::yield_now().await;
                continue;
            }
            if progress.more_immediate_work {
                if reg_tx_left == 0 {
                    break;
                }
                tokio::task::yield_now().await;
                continue;
            }
            if progress.awaiting_reply {
                if reg_tx_left == 0 || wait_polls_for_req >= MAX_OFF_LOCK_POLLS_PER_REQ {
                    break;
                }
                if now + OFF_LOCK_REPLY_POLL_INTERVAL + Duration::from_millis(1) >= comm_wait_cap {
                    break;
                }
                wait_polls_for_req = wait_polls_for_req.saturating_add(1);
                tokio::time::sleep(OFF_LOCK_REPLY_POLL_INTERVAL).await;
                continue;
            }
            break;
        }
    }

    /// Routes one [`ConfigRequest`] through the active single owner (`Legacy` write lock or
    /// `Executor` `MaintenanceOp::Config`) using the identical owner-side handler.
    pub async fn dispatch_config_request(
        &self,
        req: crate::rt_core::requests::config::ConfigRequest,
    ) -> Result<
        crate::rt_core::requests::config::ConfigReply,
        crate::rt_core::requests::config::ConfigError,
    > {
        use crate::rt_core::executor::OwnerError;
        use crate::rt_core::requests::config::{
            handle_config_exchange, ConfigError, ConfigExchange,
        };
        match self.owner_mode() {
            OWNER_EXECUTOR => {
                let Some(handle) = self.executor_handle() else {
                    return Err(ConfigError::OwnerStopped);
                };
                handle.call_config_async(req).await.map_err(|e| match e {
                    OwnerError::QueueFull => ConfigError::OwnerQueueFull,
                    _ => ConfigError::OwnerStopped,
                })
            }
            OWNER_LEGACY => {
                let cmd_label = req.command_label();
                let mut ex = ConfigExchange::new(req);
                let mut inner = self.inner.write().await;
                inner.set_command(cmd_label);
                if inner.detached {
                    drop(inner);
                    let req = ex.req.take().expect("request still present");
                    if self.owner_mode() == OWNER_EXECUTOR {
                        let Some(handle) = self.executor_handle() else {
                            return Err(ConfigError::OwnerStopped);
                        };
                        return handle.call_config_async(req).await.map_err(|e| match e {
                            OwnerError::QueueFull => ConfigError::OwnerQueueFull,
                            _ => ConfigError::OwnerStopped,
                        });
                    }
                    return Err(ConfigError::OwnerStopped);
                }
                let ctx = crate::rt_core::ops::CommitCtx {
                    arm: inner.core.id(),
                    boot: crate::rt_core::broker::BootId::process(),
                    now: Instant::now(),
                    stop_generation: inner.current_stop_gen(),
                };
                handle_config_exchange(&mut inner, &ctx, &mut ex);
                drop(inner);
                ex.reply.take().ok_or(ConfigError::OwnerStopped)
            }
            _ => Err(ConfigError::OwnerStopped),
        }
    }

    /// Dispatches a `ConfigRequest` that must survive transient `MaintenanceOp` queue
    /// backpressure (used for `Persisted`, `Activate`, `Release`, `VerifyAuthority`,
    /// `CalibrationRevert`, and `SetCalibrationBusy(false)` cleanup).
    ///
    /// Retries `ConfigError::OwnerQueueFull` with short bounded backoff while the owner is
    /// still alive; returns immediately on any non-backpressure outcome or `OwnerStopped`.
    pub async fn dispatch_config_request_reliable(
        &self,
        mut build_req: impl FnMut() -> crate::rt_core::requests::config::ConfigRequest,
    ) -> Result<
        crate::rt_core::requests::config::ConfigReply,
        crate::rt_core::requests::config::ConfigError,
    > {
        use crate::rt_core::requests::config::ConfigError;
        let mut backoff_ms = 1u64;
        loop {
            match self.dispatch_config_request(build_req()).await {
                Err(ConfigError::OwnerQueueFull) => {
                    if self.owner_mode() == OWNER_EXECUTOR
                        && self.executor_handle().is_none_or(|h| h.is_exited())
                    {
                        return Err(ConfigError::OwnerStopped);
                    }
                    tokio::time::sleep(Duration::from_millis(backoff_ms)).await;
                    backoff_ms = (backoff_ms * 2).min(10);
                }
                other => return other,
            }
        }
    }

    /// Dispatches a one-shot non-Clone `ConfigRequest` (e.g., carrying a unique `Reservation`
    /// token or `ConfigCandidate`) with guaranteed retry across transient `OwnerQueueFull`.
    /// When the executor queue is full, `MaintClient::call_config_retryable_async` returns the
    /// exact untouched `ConfigRequest` so ownership is never lost.
    pub async fn dispatch_config_request_owned_reliable(
        &self,
        mut req: crate::rt_core::requests::config::ConfigRequest,
    ) -> Result<
        crate::rt_core::requests::config::ConfigReply,
        crate::rt_core::requests::config::ConfigError,
    > {
        use crate::rt_core::requests::config::{
            handle_config_exchange, ConfigError, ConfigExchange,
        };
        let mut backoff_ms = 1u64;
        loop {
            match self.owner_mode() {
                OWNER_EXECUTOR => {
                    let Some(handle) = self.executor_handle() else {
                        return Err(ConfigError::OwnerStopped);
                    };
                    if handle.is_exited() {
                        return Err(ConfigError::OwnerStopped);
                    }
                    match handle.call_config_try_async(req).await {
                        Ok(reply) => return Ok(reply),
                        Err((returned_req, crate::rt_core::executor::OwnerError::QueueFull)) => {
                            req = returned_req;
                            tokio::time::sleep(Duration::from_millis(backoff_ms)).await;
                            backoff_ms = (backoff_ms * 2).min(10);
                        }
                        Err((_, _)) => return Err(ConfigError::OwnerStopped),
                    }
                }
                OWNER_LEGACY => {
                    let cmd_label = req.command_label();
                    let mut ex = ConfigExchange::new(req);
                    let mut inner = self.inner.write().await;
                    inner.set_command(cmd_label);
                    if inner.detached {
                        drop(inner);
                        req = ex.req.take().expect("request still present");
                        continue;
                    }
                    let ctx = crate::rt_core::ops::CommitCtx {
                        arm: inner.core.id(),
                        boot: crate::rt_core::broker::BootId::process(),
                        now: Instant::now(),
                        stop_generation: inner.current_stop_gen(),
                    };
                    handle_config_exchange(&mut inner, &ctx, &mut ex);
                    drop(inner);
                    return ex.reply.take().ok_or(ConfigError::OwnerStopped);
                }
                _ => return Err(ConfigError::OwnerStopped),
            }
        }
    }

